  ComposerAttachment,
  ComposerControlsProps,
  ComposerSubmitRequest,
};

import {
  classifyFailure,
  normalizeDiagnosticsId,
  redactReportMessage,
} from "@/components/composer/diagnostics-report";
import type {
  DiagnosticsSurface,
  FailureClassification,
} from "@/components/composer/diagnostics-report";
import type { SubmitDiagnosticsHost } from "@/components/composer/submit-error";

/*
 * The diagnostics host behind the "View diagnostics" toast action: the host
 * function with its store and view selector. The gate, the router and the host
 * lookup are
 * the app services the component reads; here each is a function the caller
 * supplies, so a demonstration drives them with local data.
 */

interface DiagnosticsReportInput {
  conversationId: string | null;
  errorMessage: string;
  occurredAtMs: number;
  operation: string;
  surface: DiagnosticsSurface;
}

/** The report as the diagnostics view reads it. */
interface DiagnosticsReport extends DiagnosticsReportInput {
  initialClassification: FailureClassification;
}

/** The stored report with where it was made. */
interface StoredDiagnostics {
  hostId: string | null;
  pathname: string | null;
  report: DiagnosticsReport;
}

/** The router the click navigates with. Each navigation says whether it happened. */
interface DiagnosticsRouter {
  /** The conversation id of the current route. */
  conversationIdFromPath: (pathname: string) => string | null;
  navigate: (path: string) => boolean;
  navigateToLocalConversation: (
    conversationId: string,
    hostId?: string
  ) => boolean;
  pathForConversation: (conversationId: string) => string;
  pathname: string | null;
}

interface DiagnosticsHostServices {
  /** The diagnostics feature gate. */
  isGateOn: () => boolean;
  /** The host a code conversation runs on ("local" or a remote host id). */
  hostIdFor: (conversationId: string | null) => string | null | undefined;
  router: () => DiagnosticsRouter;
}

/** What the diagnostics view is showing. */
interface DiagnosticsViewContext {
  conversationId: string | null;
  hostId: string | null;
  pathname: string | null;
  surface: DiagnosticsSurface;
}

const createDiagnosticsStore = () => {
  let current: StoredDiagnostics | null = null;
  const listeners = new Set<() => void>();

  return {
    get: () => current,
    /** The stored report when it belongs to what the view shows, else null. */
    select: (view: DiagnosticsViewContext) => {
      if (
        current === null ||
        current.report.surface !== view.surface ||
        current.hostId !== view.hostId
      ) {
        return null;
      }

      if (current.report.conversationId === null) {
        return current.pathname === view.pathname ? current : null;
      }

      return current.report.conversationId === view.conversationId
        ? current
        : null;
    },
    set: (next: StoredDiagnostics | null) => {
      current = next;

      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener: () => void) => {
      listeners.add(listener);

      return () => {
        listeners.delete(listener);
      };
    },
  };
};

type DiagnosticsStore = ReturnType<typeof createDiagnosticsStore>;

const prepareReport = (
  services: DiagnosticsHostServices,
  input: DiagnosticsReportInput
) => {
  const report: DiagnosticsReport = {
    ...input,
    conversationId: normalizeDiagnosticsId(input.conversationId),
    errorMessage: redactReportMessage(input.errorMessage),
    initialClassification: classifyFailure(
      input.errorMessage,
      undefined,
      input.surface
    ),
  };

  return {
    hostId:
      input.surface === "code"
        ? (services.hostIdFor(report.conversationId) ?? null)
        : null,
    pathname: services.router().pathname ?? null,
    report,
  };
};

/** The click handler of one prepared diagnostics report. */
const clickHandlerFor = (
  services: DiagnosticsHostServices,
  store: DiagnosticsStore,
  prepared: {
    hostId: string | null;
    pathname: string | null;
    report: DiagnosticsReport;
  }
) => {
  const { hostId, pathname, report } = prepared;

  /** Whether the router agreed to show the report's place; the report is stored only then. */
  const navigate = () => {
    const router = services.router();

    if (report.conversationId === null) {
      return (
        pathname === null ||
        pathname === router.pathname ||
        router.navigate(pathname)
      );
    }

    if (report.surface === "code") {
      const target = hostId === "local" ? undefined : (hostId ?? undefined);

      return router.navigateToLocalConversation(report.conversationId, target);
    }

    return (
      router.conversationIdFromPath(router.pathname ?? "") ===
        report.conversationId ||
      router.navigate(router.pathForConversation(report.conversationId))
    );
  };

  return () => {
    if (services.isGateOn() && navigate()) {
      store.set({ hostId, pathname, report });
    }
  };
};

/**
 * With the gate off `prepare` returns nothing and the toast has no
 * action. With it on, `prepare` builds the report now (classified, scrubbed,
 * with a checked conversation id and the current pathname) and returns the
 * click handler, which navigates and then stores the report for the view.
 */
const createDiagnosticsHost = (
  services: DiagnosticsHostServices,
  store: DiagnosticsStore
): SubmitDiagnosticsHost => ({
  prepare: (input: DiagnosticsReportInput) =>
    services.isGateOn()
      ? clickHandlerFor(services, store, prepareReport(services, input))
      : undefined,
});

export { createDiagnosticsHost, createDiagnosticsStore };

export type {
  DiagnosticsHostServices,
  DiagnosticsReport,
  DiagnosticsReportInput,
  DiagnosticsRouter,
  DiagnosticsStore,
  DiagnosticsViewContext,
  StoredDiagnostics,
};

/* oxlint-disable eslint/max-lines, eslint/no-useless-escape, eslint/no-control-regex, eslint/require-unicode-regexp, eslint/prefer-regex-literals, eslint/prefer-named-capture-group, unicorn/new-for-builtins -- Credential patterns and report classification rules share this module. */

/*
 * Detect credentials before diagnostics leave the composer. Format-specific
 * rules cover keys and service tokens; generic rules cover connection strings,
 * headers and assignments. Report scrubbers remove private details, while
 * classification rules identify likely causes of a failure.
 */

interface SecretRule {
  pattern: RegExp;
  prefilters: readonly string[];
  /** The capture group that holds the secret. Without one, the whole match is the secret. */
  secretGroup?: number;
  skipPlaceholderCheck?: boolean;
  validate?: (secret: string, match: RegExpMatchArray) => boolean;
}

const vendorRule = (pattern: RegExp, ...prefilters: string[]): SecretRule => ({
  pattern,
  prefilters,
});

/** Group 1 of the named secret pattern holds the name of the variable. */
const NAMED_SECRET_NAME_GROUP = 1;

/** A secret needs this many distinct characters at least and no placeholder look. */
const MIN_DISTINCT_CHARACTERS = 4;
const MAX_SECRET_LENGTH = 4096;
const MIN_URL_PASSWORD_LENGTH = 8;
const MIN_NAMED_SECRET_LENGTH = 16;
const MIN_PASSWORD_LENGTH = 8;
const MAX_PLACEHOLDER_DISTINCT_CHARACTERS = 3;

const PLACEHOLDER_WORDS = [
  "example",
  "dummy",
  "placeholder",
  "changeme",
  "replace_me",
  "redacted",
  "masked",
];

const PLACEHOLDER_NAMES = new Set([
  "password",
  "passwd",
  "secret",
  "token",
  "apikey",
  "api_key",
  "none",
  "null",
  "true",
  "false",
  "undefined",
]);

const stripQuotes = (value: string) =>
  value.trim().replaceAll(/^["']+|["']+$/g, "");

/** Text that looks like a placeholder, not a secret. */
const looksLikePlaceholder = (value: string) => {
  const text = stripQuotes(value);
  const lower = text.toLowerCase();

  if (
    lower.length === 0 ||
    lower.startsWith("${") ||
    lower.startsWith("$(") ||
    lower.startsWith("{{") ||
    lower.startsWith("<") ||
    lower.startsWith("[") ||
    lower.startsWith("process.env") ||
    lower.startsWith("os.environ") ||
    /^\$[A-Za-z_][A-Za-z0-9_]*$/.test(text) ||
    PLACEHOLDER_WORDS.some((word) => lower.includes(word))
  ) {
    return true;
  }

  return (
    PLACEHOLDER_NAMES.has(lower) ||
    new Set(text).size <= MAX_PLACEHOLDER_DISTINCT_CHARACTERS
  );
};

const isStrongSecret = (value: string, minimumLength: number) => {
  const text = stripQuotes(value);

  return (
    text.length >= minimumLength &&
    text.length <= MAX_SECRET_LENGTH &&
    !looksLikePlaceholder(text) &&
    !/^\d+$/.test(text) &&
    new Set(text).size >= MIN_DISTINCT_CHARACTERS
  );
};

const validateLongSecret = (value: string) =>
  isStrongSecret(value, MIN_NAMED_SECRET_LENGTH);

/** A named secret (TOKEN=...) is not a URL and is long enough, passwords shorter. */
const validateNamedSecret = (value: string, match: RegExpMatchArray) => {
  const name = match[NAMED_SECRET_NAME_GROUP]?.toUpperCase();

  if (name === undefined || value.includes("://")) {
    return false;
  }

  const isPassword = ["PASSWORD", "PASSWD", "_PWD"].some((part) =>
    name.includes(part)
  );

  return isStrongSecret(
    value,
    isPassword ? MIN_PASSWORD_LENGTH : MIN_NAMED_SECRET_LENGTH
  );
};

/** Credentials in a URL, with a password of at least eight characters. */
const validateUrlCredentials = (value: string) => {
  const match = /^[A-Za-z][A-Za-z0-9+.-]*:\/\/([^:/@]+):([^@]+)@/.exec(value);

  return match !== null && isStrongSecret(match[2], MIN_URL_PASSWORD_LENGTH);
};

/** Lines kept in a report message. */
const MAX_REPORT_LINES = 5;

/** Characters kept in a report message. */
const MAX_REPORT_LENGTH = 700;

/** Characters of the message that are scrubbed. */
const MAX_MESSAGE_LENGTH = 4096;

/** Characters of the message that are classified. */
const MAX_CLASSIFIED_LENGTH = 32_768;

/** A line that holds an email address. */
const EMAIL_LINE =
  /(?:"[^"\r\n]+"|[\p{L}\p{N}.!#$%&'*+/=?^_`{|}~-])(?:@|%40|\\u0040)/iu;

/** A line that holds an absolute or relative path. */
const PATH_LINE =
  /(?:^|[\s"'`(<=>:,])(?:file:\/\/|[a-z]:[\\/]|\\|\/(?!\/)|~[\\/]|\.{1,2}[\\/]|(?:[a-z]%3a)?%(?:2f|5c))/iu;

/** A line that holds a path segment. */
const RELATIVE_PATH_LINE = /(?:^|[\s"'`(<=>,])[\p{L}\p{N}_.-]+[\\/](?!\/)/iu;

/** The names that mark a value as secret. */
const SECRET_NAMES = String.raw`(?:authorization|token|secret|api[_-]?key|access[_-]?key|cookie|password|passwd|pwd|passcode|credential|private[_-]?key|otp|database[_-]?url|db[_-]?url|postgres[_-]?url|redis[_-]?url|mongodb[_-]?uri)`;

const JSON_SECRET_PAIR = new RegExp(
  String.raw`"([^"]*${SECRET_NAMES}[^"]*)"\s*:\s*"(?:\\.|[^"\\])*"`,
  `gi`
);

const SINGLE_QUOTED_SECRET_PAIR = new RegExp(
  String.raw`'([^']*${SECRET_NAMES}[^']*)'\s*:\s*'(?:\\.|[^'\\])*'`,
  `gi`
);

const ENV_SECRET_ASSIGNMENT = new RegExp(
  String.raw`\b([A-Z0-9_-]*${SECRET_NAMES}[A-Z0-9_-]*)\s*=\s*(?:"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|[^\s]+)`,
  `gi`
);

const SECRET_HEADER_LINE = new RegExp(
  String.raw`\b(?!Authorization\s*:|Cookie\s*:)[A-Z0-9_-]*${SECRET_NAMES}[A-Z0-9_-]*\s*:\s*[^\n]+`,
  `gi`
);

const QUERY_SECRET_PAIR = new RegExp(
  String.raw`\b([A-Z0-9_-]*${SECRET_NAMES}[A-Z0-9_-]*)=([^&\s]+)`,
  `gi`
);

const URL_CREDENTIALS =
  /\b([A-Za-z][A-Za-z0-9+.-]*:\/\/)[^\s/?#:"<>]*:[^\s/?#"<>]*@/g;

const TRUNCATED_URL_CREDENTIALS =
  /\b([A-Za-z][A-Za-z0-9+.-]*:\/\/)[^\s/?#:"<>]*:[^\s/?#"<>]*$/g;

const TRUNCATED_JSON_SECRET = new RegExp(
  String.raw`((?:"[^"\r\n]*${SECRET_NAMES}[^"\r\n]*"|'[^'\r\n]*${SECRET_NAMES}[^'\r\n]*'|\b[A-Z0-9_-]*${SECRET_NAMES}[A-Z0-9_-]*\b)\s*[:=]\s*)"(?:\\[\s\S]|[^"\\])*\\?$`,
  `i`
);

const TRUNCATED_SINGLE_QUOTED_SECRET = new RegExp(
  String.raw`((?:"[^"\r\n]*${SECRET_NAMES}[^"\r\n]*"|'[^'\r\n]*${SECRET_NAMES}[^'\r\n]*'|\b[A-Z0-9_-]*${SECRET_NAMES}[A-Z0-9_-]*\b)\s*[:=]\s*)'(?:\\[\s\S]|[^'\\])*\\?$`,
  `i`
);

/** How specific a classification signal is. */
const SPECIFICITY = {
  broad: 55,
  contextual: 145,
  descriptive: 105,
  exact: 135,
  generic: 75,
  protocol: 125,
  strong: 115,
};

/** PEM and armored private keys, including encrypted key blocks. */
