  EMAIL_LINE,
  ENV_SECRET_ASSIGNMENT,
  GENERIC_RULES,
  JSON_SECRET_PAIR,
  looksLikePlaceholder,
  MAX_CLASSIFIED_LENGTH,
  MAX_MESSAGE_LENGTH,
