  RELATIVE_PATH_LINE,
  SECRET_HEADER_LINE,
  SINGLE_QUOTED_SECRET_PAIR,
  TRUNCATED_JSON_SECRET,
  TRUNCATED_SINGLE_QUOTED_SECRET,
  TRUNCATED_URL_CREDENTIALS,
  URL_CREDENTIALS,
  VENDOR_RULES,
} from "@/components/composer/diagnostics-patterns";
import type { SecretRule } from "@/components/composer/diagnostics-patterns";

/*
 * Builds the report for the diagnostics view. It classifies the failure,
 * scrubs secrets and private details from the message, and keeps the
 * conversation id only when it is a plain id. The tables are in
 * diagnostics-patterns.ts.
 */

const REDACTION_TOKEN = "<SECRET>";
const LOOSE_PREFILTERS = new Set(["us", "at"]);
const REDACTED = "[removed_secret]";
const CONVERSATION_ID = /^[a-z0-9][a-z0-9_.-]{0,127}$/iu;
const API_KEY_PREFIX = /^sk-/iu;

interface Range {
  end: number;
  start: number;
}

const escapeForPattern = (text: string) =>
  text.replaceAll(/[.*+?^${}()|[\]\\]/gu, String.raw`\$&`);

/** Every vendor prefix, longest first, as one scan of the lowercased text. */
const PREFILTER_SCAN = new RegExp(
  [
    ...new Set(
      VENDOR_RULES.flatMap((rule) => rule.prefilters).filter(
        (prefilter) => !LOOSE_PREFILTERS.has(prefilter)
      )
    ),
  ]
    .toSorted((first, second) => second.length - first.length)
    .map(escapeForPattern)
    .join("|"),
  "gu"
);

const hasPrefilter = (
  lower: string,
  prefilter: string,
  present: ReadonlySet<string> | null
) =>
  present === null || LOOSE_PREFILTERS.has(prefilter)
    ? lower.includes(prefilter)
    : present.has(prefilter);

/** Where one rule finds a secret. */
const ruleRanges = (
  text: string,
  lower: string,
  rule: SecretRule,
  present: ReadonlySet<string> | null = null
): Range[] => {
  if (
    !rule.prefilters.some((prefilter) =>
      hasPrefilter(lower, prefilter, present)
    )
  ) {
    return [];
  }

  const ranges: Range[] = [];

  for (const match of text.matchAll(rule.pattern)) {
    const secret = match[rule.secretGroup ?? 0];

    if (rule.skipPlaceholderCheck !== true && looksLikePlaceholder(secret)) {
      continue;
    }

    if (rule.validate !== undefined && !rule.validate(secret, match)) {
      continue;
    }

    const offset = match[0].lastIndexOf(secret);

    if (offset === -1) {
      continue;
    }

    const start = (match.index ?? 0) + offset;
    ranges.push({ end: start + secret.length, start });
  }

  return ranges;
};

/** Sorts ranges and joins the ones that overlap. */
const mergeRanges = (ranges: readonly Range[]) => {
  const merged: Range[] = [];

  for (const range of ranges.toSorted(
    (first, second) => first.start - second.start || first.end - second.end
  )) {
    const last = merged.at(-1);

    if (last === undefined || range.start > last.end) {
      merged.push({ ...range });
    } else {
      last.end = Math.max(last.end, range.end);
    }
  }

  return merged;
};

const privateKeyRanges = (text: string): Range[] =>
  text.includes("-----BEGIN")
    ? [...text.matchAll(PRIVATE_KEY_BLOCK)].map((match) => ({
        end: (match.index ?? 0) + match[0].length,
        start: match.index ?? 0,
      }))
    : [];

const DATA_IMAGE = /^data:image\/[A-Za-z0-9.+-]+;base64,/iu;

/** For a string: the findings and the text with each one replaced. */
const scanSecrets = (text: string) => {
  if (DATA_IMAGE.test(text)) {
    return { findingCount: 0, redacted: text };
  }

  const lower = text.toLowerCase();
  const present = new Set([...lower.matchAll(PREFILTER_SCAN)].map((m) => m[0]));

  const ranges = mergeRanges([
    ...privateKeyRanges(text),
    ...VENDOR_RULES.flatMap((rule) => ruleRanges(text, lower, rule, present)),
    ...GENERIC_RULES.flatMap((rule) => ruleRanges(text, lower, rule)),
  ]);

  if (ranges.length === 0) {
    return { findingCount: 0, redacted: text };
  }

  const parts: string[] = [];
  let cursor = 0;

  for (const range of ranges) {
    parts.push(text.slice(cursor, range.start), REDACTION_TOKEN);
    cursor = range.end;
  }

  parts.push(text.slice(cursor));

  return { findingCount: ranges.length, redacted: parts.join("") };
};

/** An id that is a plain token and holds no secret, or null. */
const normalizeDiagnosticsId = (id: string | null | undefined) =>
  id !== null &&
  id !== undefined &&
  CONVERSATION_ID.test(id) &&
  !API_KEY_PREFIX.test(id) &&
  scanSecrets(id).findingCount === 0
    ? id
    : null;

/** A message cut at the limit may end inside a secret. */
const scrubTruncatedSecrets = (text: string, truncated: boolean) => {
  const quoted = truncated
    ? text
        .replace(TRUNCATED_JSON_SECRET, `$1"${REDACTED}"`)
        .replace(TRUNCATED_SINGLE_QUOTED_SECRET, `$1'${REDACTED}'`)
    : text;

  const urls = truncated
    ? quoted.replace(TRUNCATED_URL_CREDENTIALS, `$1${REDACTED}`)
    : quoted;

  return urls.replace(URL_CREDENTIALS, `$1${REDACTED}@`);
};

/** The message of the report, scrubbed of secrets, addresses and paths. */
const redactReportMessage = (message: string) => {
  const head = message.slice(0, MAX_MESSAGE_LENGTH);

  const scrubbed = scanSecrets(
    scrubTruncatedSecrets(head, message.length > head.length)
  )
    .redacted.replaceAll(
      /-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?PRIVATE KEY-----[\s\S]*/gu,
      "[removed_private_key]"
    )
    .replaceAll(
      /\bAuthorization:\s*Bearer\s+[^\s]+/giu,
      "Authorization: Bearer [removed_bearer_token]"
    )
    .replaceAll(
      /\bAuthorization:(?![ \t]*Bearer\b)[^\n]+/giu,
      `Authorization: ${REDACTED}`
    )
    .replaceAll(/\bBearer\s+[^\s]+/giu, "Bearer [removed_bearer_token]")
    .replaceAll(/\bCookie:\s*[^\n]+/giu, "Cookie: [removed_cookie]")
    .replace(JSON_SECRET_PAIR, `"$1": "${REDACTED}"`)
    .replace(SINGLE_QUOTED_SECRET_PAIR, `'$1': '${REDACTED}'`)
    .replace(ENV_SECRET_ASSIGNMENT, `$1=${REDACTED}`)
    .replace(
      SECRET_HEADER_LINE,
      (line) => `${line.slice(0, line.indexOf(":"))}: ${REDACTED}`
    )
    .replace(QUERY_SECRET_PAIR, `$1=${REDACTED}`)
    .replaceAll(/\bsk-[A-Za-z0-9_-]{8,}\b/gu, "[removed_api_key]");

  const text = scrubbed
    .split(/\r?\n/u)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) =>
      EMAIL_LINE.test(line) ||
      PATH_LINE.test(line) ||
      RELATIVE_PATH_LINE.test(line)
        ? "[removed_private_details]"
        : line
    )
    .slice(0, MAX_REPORT_LINES)
    .join("\n");

  return text.length <= MAX_REPORT_LENGTH
    ? text
    : `${text.slice(0, MAX_REPORT_LENGTH)}…`;
};

type DiagnosticsSurface = "chat" | "code";

interface FailureClassification {
  category: string;
  confidence: string;
  matchedSignal: string | null;
}

/**
 * The category of the signal with the highest specificity that
 * matches the message. The chat surface skips workspace setup and sandbox
 * approval rules.
 */
const classifyFailure = (
  message: string,
  detail: string | undefined,
  surface: DiagnosticsSurface = "code"
): FailureClassification => {
  const text = [message, detail ?? ""]
    .map((part) => part.slice(0, MAX_CLASSIFIED_LENGTH))
    .join("\n");

  let best: {
    confidence: string;
    category: string;
    specificity: number;
    type: string;
  } | null = null;

  for (const rule of CLASSIFICATION_RULES) {
    if (
      surface === "chat" &&
      (rule.category === "workspace_setup" ||
        rule.category === "sandbox_approval")
    ) {
      continue;
    }

    for (const signal of rule.signals) {
      if (
        signal.pattern.test(text) &&
        (best === null || signal.specificity > best.specificity)
      ) {
        best = {
          category: rule.category,
          confidence: rule.confidence,
          specificity: signal.specificity,
          type: signal.type,
        };
      }
    }
  }

  return best === null
    ? { category: "unknown", confidence: "low", matchedSignal: null }
    : {
        category: best.category,
        confidence: best.confidence,
        matchedSignal: best.type,
      };
};

export {
  classifyFailure,
  normalizeDiagnosticsId,
  redactReportMessage,
  scanSecrets,
};

export type { DiagnosticsSurface, FailureClassification };

"use client";

import { ComposerEditorController } from "@/components/composer/editor/controller";
import type { ComposerEditorKeyContext } from "@/components/composer/editor/controller";
import { MENTION_ATTRIBUTE } from "@/components/composer/editor/schema";
import { InlineMention } from "@/components/ui/mention";
import type { Node as ProseMirrorNode } from "prosemirror-model";
import type { NodeViewConstructor } from "prosemirror-view";
import { useEffect, useEffectEvent, useRef } from "react";
import type { RefObject } from "react";
import { createRoot } from "react-dom/client";
import type { Root } from "react-dom/client";

import styles from "@/components/composer/editor/editor.module.css";

/*
 * The editor view of the composer: a ProseMirror view mounted in a div, with
 * mention and skill mention node views drawn by the mention family's
 * InlineMention. The controller is handed to the caller through `controllerRef`
 * so a tip, a dictation source or a toolbar can drive it.
 */

const mentionNodeView =
  (kind: "mention" | "skillMention"): NodeViewConstructor =>
  (node) => {
    const dom = document.createElement("span");
    dom.className = styles.Mention;
    dom.contentEditable = "false";
    dom.setAttribute(MENTION_ATTRIBUTE, kind);
    let root: Root | undefined = createRoot(dom);

    const render = (current: ProseMirrorNode) => {
      root?.render(
        <InlineMention>{String(current.attrs.displayName)}</InlineMention>
      );
    };

    render(node);

    return {
      destroy: () => {
        const pending = root;
        root = undefined;
        queueMicrotask(() => pending?.unmount());
      },
      dom,
      ignoreMutation: () => true,
      update: (next) => {
        if (next.type !== node.type) {
          return false;
        }

        render(next);

        return true;
      },
    };
  };

const nodeViews = {
  mention: mentionNodeView("mention"),
  skillMention: mentionNodeView("skillMention"),
};

interface ComposerEditorProps {
  "aria-label"?: string;
  className?: string;
  controllerRef?: RefObject<ComposerEditorController | null>;
  doc?: ProseMirrorNode;
  editable?: boolean;
  keyContext?: Partial<ComposerEditorKeyContext>;
  onChange?: (doc: ProseMirrorNode) => void;
  placeholder?: string;
}

const releaseNothing = () => {
  /* there was no element to mount into, so there is nothing to release */
};

const ComposerEditor = ({
  "aria-label": ariaLabel,
  className,
  controllerRef,
  doc,
  editable = true,
  keyContext,
  onChange,
  placeholder,
}: ComposerEditorProps) => {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<ComposerEditorController | null>(null);
  const initialKeyContext = useEffectEvent(() => keyContext);
  const initialPlaceholder = useEffectEvent(() => placeholder);

  const reportChange = useEffectEvent((next: ProseMirrorNode) => {
    onChange?.(next);
  });

  useEffect(() => {
    const element = host.current;

    if (element === null) {
      return releaseNothing;
    }

    const created = new ComposerEditorController({
      className:
        className === undefined || className === ""
          ? styles.Editor
          : `${styles.Editor} ${className}`,
      doc,
      editable,
      element,
      keyContext: initialKeyContext(),
      nodeViews,
      onChange: reportChange,
      placeholder: initialPlaceholder(),
    });

    if (ariaLabel !== undefined && ariaLabel !== "") {
      created.view.dom.setAttribute("aria-label", ariaLabel);
    }

    controller.current = created;

    if (controllerRef) {
      controllerRef.current = created;
    }

    return () => {
      if (controllerRef) {
        controllerRef.current = null;
      }

      controller.current = null;
      created.destroy();
    };
    // oxlint-disable-next-line react/exhaustive-effect-dependencies -- the view is created once per mount; later key context and placeholder changes flow through the effects below
  }, [ariaLabel, className, controllerRef, doc, editable]);

  useEffect(() => {
    if (keyContext) {
      controller.current?.setKeyContext(keyContext);
    }
  }, [keyContext]);

  useEffect(() => {
    controller.current?.setPlaceholder(placeholder ?? "");
  }, [placeholder]);

  return <div ref={host} />;
};

export { ComposerEditor };

export type { ComposerEditorProps };

import {
  isMentionNode,
  composerSchema,
} from "@/components/composer/editor/schema";
import type { ComposerMentionAttributes } from "@/components/composer/editor/schema";
import { submitsOnEnter } from "@/components/composer/rules";
import type { ComposerEnterBehavior } from "@/components/composer/rules";
import { handleComposerShortcutKey } from "@/components/ui/composer";
import type { SelectedMode } from "@/components/ui/composer";
import {
  baseKeymap,
  chainCommands,
  exitCode,
  toggleMark,
} from "prosemirror-commands";
import { history, redo, undo } from "prosemirror-history";
import {
  InputRule,
  ellipsis,
  emDash,
  inputRules,
  smartQuotes,
} from "prosemirror-inputrules";
import { keymap } from "prosemirror-keymap";
import type { Node as ProseMirrorNode } from "prosemirror-model";
import { EditorState, Plugin, PluginKey, Selection } from "prosemirror-state";
import type { Transaction } from "prosemirror-state";
import { Decoration, DecorationSet, EditorView } from "prosemirror-view";
import type { NodeViewConstructor } from "prosemirror-view";

/*
 * The composer editor engine: a ProseMirror editor and its controller class.
 * The plugin set: history with a 500 ms group delay and Mod-z, Mod-y and
 * Mod-Shift-z, the typography input rules (-- to an em dash, ... to an ellipsis, curly quotes), the
 * placeholder decoration (a node decoration with class prosemirror-placeholder
 * and data-placeholder on an empty single paragraph), the base keymap and the
 * key routing for Enter, Escape and Backspace.
 */

const HISTORY_GROUP_DELAY_MS = 500;
const IME_KEY_CODE = 229;

const formattingRule = (
  pattern: RegExp,
  mark: "strong" | "em" | "code" | "strike"
) =>
  new InputRule(pattern, (state, match, start, end) => {
    const [, prefix, content, trailing] = match;
    const from = start + prefix.length;

    return state.tr
      .replaceWith(from, end, [
        composerSchema.text(content, [composerSchema.marks[mark].create()]),
        composerSchema.text(trailing),
      ])
      .removeStoredMark(composerSchema.marks[mark]);
  });

// The input rule handler reads capture groups by position.
/* oxlint-disable eslint/prefer-named-capture-group */
const formattingRules = [
  formattingRule(/(^|[^*])\*\*([^\s*](?:.*?[^\s*])?)\*\*([^*])$/u, "strong"),
  formattingRule(/(^|[^\w_])__([^\s_](?:.*?[^\s_])?)__([^\w_])$/u, "strong"),
  formattingRule(/(^|[^*])\*([^\s*](?:.*?[^\s*])?)\*([^*])$/u, "em"),
  formattingRule(/(^|[^_])_([^\s_](?:.*?[^\s_])?)_([^_])$/u, "em"),
  formattingRule(/(^|[^`])`([^`]+)`([^`])$/u, "code"),
  formattingRule(/(^|[^~])~~([^~]+)~~([^~])$/u, "strike"),
];
/* oxlint-enable eslint/prefer-named-capture-group */

/** The range a dictation transcript was inserted at. */
interface InsertedTranscript {
  from: number;
  to: number;
}

const transcriptKey = new PluginKey<InsertedTranscript | null>(
  "composer-transcript"
);

const placeholderKey = new PluginKey<string>("composer-placeholder");

/** The live inputs of the key routing, read at every key press. */
interface ComposerEditorKeyContext {
  enterBehavior: ComposerEnterBehavior;
  handleEscape: () => void;
  hasActiveMentionMenu: boolean;
  hasDefaultMode: boolean;
  isPlanMode: boolean;
  onSubmit: () => void;
  setSelectedMode: (mode: SelectedMode) => void;
}

const doNothing = () => {
  /* the default key context has nothing to run */
};

const defaultKeyContext: ComposerEditorKeyContext = {
  enterBehavior: "enter",
  handleEscape: doNothing,
  hasActiveMentionMenu: false,
  hasDefaultMode: true,
  isPlanMode: false,
  onSubmit: doNothing,
  setSelectedMode: doNothing,
};

const isComposingKey = (event: KeyboardEvent) =>
  // oxlint-disable-next-line typescript/no-deprecated -- the component checks keyCode 229 for an IME composition
  event.isComposing || event.keyCode === IME_KEY_CODE;

/** True when the document has more than one line (a second block or a line break). */
const isMultilineDocument = (doc: ProseMirrorNode) => {
  if (doc.childCount > 1) {
    return true;
  }

  let multiline = false;

  doc.descendants((node) => {
    if (node.type.name === "hardBreak") {
      multiline = true;
    }

    return !multiline;
  });

  return multiline;
};

/** Enter that submits, Escape and Backspace that leave plan mode or run the escape handler. */
const routeKey = (
  view: EditorView,
  event: KeyboardEvent,
  context: ComposerEditorKeyContext
) => {
  if (isComposingKey(event)) {
    return false;
  }

  const { selection } = view.state;

  if (
    handleComposerShortcutKey({
      event,
      handleEscape: context.handleEscape,
      hasActiveMentionMenu: context.hasActiveMentionMenu,
      hasDefaultMode: context.hasDefaultMode,
      isComposerFocused: view.hasFocus(),
      isPlanMode: context.isPlanMode,
      isSelectionAtStart: selection.empty && selection.from === 1,
      setSelectedMode: context.setSelectedMode,
    })
  ) {
    return true;
  }

  if (
    submitsOnEnter(
      event,
      context.enterBehavior,
      isMultilineDocument(view.state.doc),
      view.dom.ownerDocument.activeElement
    )
  ) {
    event.preventDefault();
    event.stopPropagation();
    context.onSubmit();

    return true;
  }

  return false;
};

const insertHardBreak = chainCommands(exitCode, (state, dispatch) => {
  dispatch?.(
    state.tr
      .replaceSelectionWith(composerSchema.nodes.hardBreak.create())
      .scrollIntoView()
  );

  return true;
});

// SAFETY: this controller is the only writer of the placeholder meta key and always writes a string.
const placeholderMeta = (transaction: Transaction) =>
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the meta is read back as the type it was written with
  transaction.getMeta(placeholderKey) as string | undefined;

// SAFETY: this controller is the only writer of the transcript meta key and always writes an InsertedTranscript.
const transcriptMeta = (transaction: Transaction) =>
  // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the meta is read back as the type it was written with
  transaction.getMeta(transcriptKey) as InsertedTranscript | undefined;

const placeholderPlugin = () =>
  new Plugin<string>({
    key: placeholderKey,
    props: {
      decorations: (state) => {
        const text = placeholderKey.getState(state) ?? "";
        const [first] = state.doc.children;

        if (
          text === "" ||
          state.doc.childCount !== 1 ||
          !first.isTextblock ||
          first.content.size !== 0
        ) {
          return null;
        }

        return DecorationSet.create(state.doc, [
          Decoration.node(0, first.nodeSize, {
            class: "prosemirror-placeholder",
            "data-placeholder": text,
          }),
        ]);
      },
    },
    state: {
      apply: (transaction, value) => placeholderMeta(transaction) ?? value,
      init: () => "",
    },
  });

const transcriptPlugin = () =>
  new Plugin<InsertedTranscript | null>({
    key: transcriptKey,
    state: {
      apply: (transaction, value) => {
        const next = transcriptMeta(transaction);

        if (next !== undefined) {
          return next;
        }

        return transaction.docChanged ? null : value;
      },
      init: () => null,
    },
  });

interface ComposerEditorOptions {
  /** SetSelectionAtStart: where the caret goes for a restored draft. */
  doc?: ProseMirrorNode;
  /** The element the editor mounts into. */
  element: HTMLElement;
  /** A class for the editor element. */
  className?: string;
  editable?: boolean;
  keyContext?: Partial<ComposerEditorKeyContext>;
  nodeViews?: Record<string, NodeViewConstructor>;
  onChange?: (doc: ProseMirrorNode) => void;
  placeholder?: string;
}

/** The controller API the component gives the tip and dictation code. */
class ComposerEditorController {
  readonly view: EditorView;
  private keyContext: ComposerEditorKeyContext;

  constructor(options: ComposerEditorOptions) {
    this.keyContext = { ...defaultKeyContext, ...options.keyContext };

    const state = EditorState.create({
      doc: options.doc,
      plugins: [
        inputRules({
          rules: [...formattingRules, emDash, ellipsis, ...smartQuotes],
        }),
        history({ newGroupDelay: HISTORY_GROUP_DELAY_MS }),
        keymap({
          "Mod-Shift-z": redo,
          "Mod-b": toggleMark(composerSchema.marks.strong),
          "Mod-i": toggleMark(composerSchema.marks.em),
          "Mod-y": redo,
          "Mod-z": undo,
        }),
        new Plugin({
          props: {
            handleKeyDown: (view, event) =>
              routeKey(view, event, this.keyContext),
          },
        }),
        keymap({ "Shift-Enter": insertHardBreak }),
        keymap(baseKeymap),
        placeholderPlugin(),
        transcriptPlugin(),
      ],
      schema: composerSchema,
    });

    this.view = new EditorView(options.element, {
      attributes: {
        "aria-multiline": "true",
        class: options.className ?? "",
        role: "textbox",
      },
      dispatchTransaction: (transaction) => {
        const next = this.view.state.apply(transaction);
        this.view.updateState(next);

        if (transaction.docChanged) {
          options.onChange?.(next.doc);
        }
      },
      editable: () => options.editable ?? true,
      nodeViews: options.nodeViews,
      state,
    });

    this.setPlaceholder(options.placeholder ?? "");
  }

  setKeyContext(context: Partial<ComposerEditorKeyContext>) {
    this.keyContext = { ...this.keyContext, ...context };
  }

  setPlaceholder(text: string) {
    this.view.dispatch(this.view.state.tr.setMeta(placeholderKey, text));
  }

  /** The prompt text, including the path of each mention. */
  getText() {
    return this.view.state.doc.textBetween(
      0,
      this.view.state.doc.content.size,
      "\n",
      (node) => {
        if (isMentionNode(node)) {
          const name = String(node.attrs.name);
          const path = String(node.attrs.path);
          const label = `$${name}`;

          return path === "" ? label : `[${label}](${path})`;
        }

        return node.type.name === "hardBreak" ? "\n" : "";
      }
    );
  }

  hasText() {
    return this.getText().trim().length > 0;
  }

  serializeDocument() {
    return JSON.stringify(this.view.state.doc.toJSON());
  }

  restoreDocument(serialized: string) {
    const doc = composerSchema.nodeFromJSON(JSON.parse(serialized));
    this.view.dispatch(
      this.view.state.tr.replaceWith(
        0,
        this.view.state.doc.content.size,
        doc.content
      )
    );
  }

  get lastInsertedTranscript() {
    return transcriptKey.getState(this.view.state) ?? null;
  }

  focus() {
    this.view.focus();
  }

  destroy() {
    this.view.destroy();
  }

  clear() {
    const { state } = this.view;

    this.view.dispatch(
      state.tr.replaceWith(0, state.doc.content.size, [
        composerSchema.nodes.paragraph.create(),
      ])
    );
  }

  /**
   * AppendText: trims the text, adds a space when the draft does not end
   * in whitespace or a mention, then inserts it at the end of the draft.
   */
  appendText(raw: string) {
    const text = raw.trim();

    if (text.length === 0) {
      return;
    }

    const current = this.getText();
    const { lastChild } = this.view.state.doc;

    const spaced =
      lastChild?.isAtom !== true && current.length > 0 && !/\s$/u.test(current)
        ? ` ${text}`
        : text;

    this.appendRaw(spaced);
    this.view.focus();
  }

  private appendRaw(text: string) {
    const { state } = this.view;
    const transaction = state.tr;
    transaction.setSelection(Selection.atEnd(transaction.doc));

    const position =
      transaction.doc.lastChild?.isAtom === true
        ? transaction.doc.content.size
        : transaction.selection.to;

    transaction.insertText(text, position, position);
    transaction.setSelection(Selection.atEnd(transaction.doc));
    this.view.dispatch(transaction);
  }

  /** InsertTextAtSelection: replaces the selection and puts the caret after the text. */
  insertTextAtSelection(text: string) {
    if (text.length === 0) {
      return;
    }

    const { state } = this.view;
    const { from, to } = state.selection;
    const lines = text.split("\n");
    const transaction = state.tr;

    if (lines.length === 1) {
      transaction.insertText(text, from, to);
      transaction.setSelection(
        Selection.near(transaction.doc.resolve(from + text.length))
      );
    } else {
      transaction.replaceWith(
        from,
        to,
        lines.flatMap((line, index) => {
          const parts =
            index === 0 ? [] : [composerSchema.nodes.hardBreak.create()];

          return line.length > 0
            ? [...parts, composerSchema.text(line)]
            : parts;
        })
      );
    }

    this.view.dispatch(transaction);
    this.view.focus();
  }

  /**
   * InsertDictationText: trims the transcript, appends it when the
   * editor holds no DOM selection, and otherwise pads it with a space on a
   * side that touches a non-space, then records the inserted range.
   */
  insertDictationText(raw: string) {
    const text = raw.trim();

    if (text.length === 0) {
      return;
    }

    const selection = this.view.dom.ownerDocument.getSelection();

    const insideEditor =
      selection !== null &&
      selection.rangeCount > 0 &&
      selection.anchorNode !== null &&
      selection.focusNode !== null &&
      this.view.dom.contains(selection.anchorNode) &&
      this.view.dom.contains(selection.focusNode);

    if (!insideEditor) {
      this.appendText(text);
      const end = this.view.state.selection.to;
      this.view.dispatch(
        this.view.state.tr.setMeta(transcriptKey, {
          from: end - text.length,
          to: end,
        })
      );

      return;
    }

    const { doc, selection: current } = this.view.state;
    const { from, to } = current;
    const before = doc.textBetween(Math.max(0, from - 1), from, "\n");
    const after = doc.textBetween(to, Math.min(doc.content.size, to + 1), "\n");
    const padStart = before.length > 0 && !/\s$/u.test(before);
    const padEnd = after.length > 0 && !/^\s/u.test(after);
    const padded = `${padStart ? " " : ""}${text}${padEnd ? " " : ""}`;
    const transaction = this.view.state.tr.insertText(padded, from, to);

    transaction.setSelection(
      Selection.near(transaction.doc.resolve(from + padded.length))
    );

    const start = from + (padStart ? 1 : 0);
    transaction.setMeta(transcriptKey, {
      from: start,
      to: start + text.length,
    });
    this.view.dispatch(transaction);
    this.view.focus();
  }

  /** InsertMentionAtSelection and insertSkillMentionAtSelection. */
  insertMentionAtSelection(
    mention: ComposerMentionAttributes,
    kind: "mention" | "skillMention" = "mention"
  ) {
    const { from, to } = this.view.state.selection;
    const node = composerSchema.nodes[kind].create(mention);
    const transaction = this.view.state.tr.replaceWith(from, to, node);

    transaction.setSelection(
      Selection.near(transaction.doc.resolve(from + node.nodeSize))
    );
    this.view.dispatch(transaction);
    this.view.focus();
  }

  insertSkillMentionAtSelection(mention: ComposerMentionAttributes) {
    this.insertMentionAtSelection(mention, "skillMention");
  }

  /** PrependAppMentions: mentions followed by a space, ahead of the first line. */
  prependMentions(mentions: readonly ComposerMentionAttributes[]) {
    const { state } = this.view;
    const { mention, paragraph } = composerSchema.nodes;

    const content = mentions.flatMap((attributes) => [
      mention.create(attributes),
      composerSchema.text(" "),
    ]);

    const [first] = state.doc.children;
    const transaction: Transaction = state.tr;

    if (first.isTextblock) {
      transaction.insert(1, content);
    } else {
      transaction.insert(0, paragraph.create(null, content));
    }

    this.view.dispatch(transaction.setMeta("addToHistory", false));
  }
}

