"use client";

/* oxlint-disable typescript/no-deprecated -- The host and composer treat keyCode 229 as an IME composition key. */

import {
  createContext,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import type { ReactNode } from "react";

/*
 * The key-command registry runs normal handlers before fallback handlers,
 * newest registration first, and stops at the first handler that does not
 * return false.
 *
 * The Electron host sends run-command messages. In a browser, dispatchEvent
 * skips prevented events and IME composition, tries commands in table order,
 * and stops at the first command whose handlers accept the key.
 */

/* ---------------------------------------------------------------- keymap */

/** Values include `keyboard_shortcut`, `host_run_command` and menu names. */
type KeyCommandSource = string;

type KeyCommandPriority = "fallback" | "normal";

/** The context a non-keyboard invocation hands to the handlers. */
type KeyCommandContext =
  | { readonly composerId?: string; readonly menuItem?: string }
  | undefined;

/** Handler contract: `false` declines, any other value accepts. */
type KeyCommandHandler = (
  source: KeyCommandSource,
  event: KeyboardEvent | undefined,
  context: KeyCommandContext
) => boolean;

interface KeyCommandOptions {
  isActive?: (context: KeyCommandContext) => boolean;
  priority?: KeyCommandPriority;
}

interface KeyBinding {
  command: string;
  /** `null` unbinds the command, as the keymap state does. */
  key: string | null;
}

interface KeyCommandKeymap {
  bindings: readonly KeyBinding[];
}

/** The commands this family handles, in the command-table order. */
const KEY_COMMAND_ORDER = [
  "composer.sendMessage",
  "composer.runInBackground",
  "composer.redirectRun",
  "composer.enqueueMessage",
  "composer.resetDraft",
  "approval.acceptRequest",
  "approval.rejectRequest",
] as const;

type KeyCommandId = (typeof KEY_COMMAND_ORDER)[number];

/**
 * A repeated key, or a bare key inside an editable target, is not a
 * command (held Enter and Enter in a select do not approve).
 */
const isEditableTarget = (target: EventTarget | null) =>
  target instanceof HTMLElement &&
  (target.isContentEditable ||
    ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));

const isKeyCommandId = (command: string): command is KeyCommandId =>
  KEY_COMMAND_ORDER.some((id) => id === command);

/**
 * Electron default bindings. The table gives approval.acceptRequest Enter and
 * approval.rejectRequest Escape; composer.sendMessage has none of its own, and the
 * component falls back to Enter when no binding is stored.
 */
const DEFAULT_KEYBINDINGS = {
  "approval.acceptRequest": ["Enter"],
  "approval.rejectRequest": ["Escape"],
  "composer.enqueueMessage": [],
  "composer.redirectRun": [],
  "composer.resetDraft": [],
  "composer.runInBackground": ["CmdOrCtrl+Enter"],
  "composer.sendMessage": ["Enter"],
} as const satisfies Record<KeyCommandId, readonly string[]>;

/** Groups of commands that never conflict because they act in different places. */
const CONFLICT_EXEMPT_GROUPS: readonly (readonly string[])[] = [
  ["tabs.closeActive", "windows.closeActive"],
  ["editor.jumpToLine", "browser.focusLocation"],
  ["editor.jumpToSymbol", "history.stepForward"],
];

/**
 * Whether two commands may share a key. A command shares with
 * itself, Enter is shared by composer.sendMessage and approval.acceptRequest, and the
 * listed groups share.
 */
const mayShareKey = (first: string, second: string, key: string) =>
  first === second ||
  (key.toLowerCase() === "enter" &&
    ((first === "composer.sendMessage" &&
      second === "approval.acceptRequest") ||
      (first === "approval.acceptRequest" &&
        second === "composer.sendMessage"))) ||
  CONFLICT_EXEMPT_GROUPS.some(
    (group) => group.includes(first) && group.includes(second)
  );

/** A stored binding replaces the default; without one the default applies. */
const keysForCommand = (
  command: string,
  keymap: KeyCommandKeymap | undefined
): readonly string[] => {
  const stored =
    keymap?.bindings.filter((binding) => binding.command === command) ?? [];

  if (stored.length > 0) {
    return stored.flatMap(({ key }) => (key === null ? [] : [key]));
  }

  return isKeyCommandId(command) ? DEFAULT_KEYBINDINGS[command] : [];
};

/** Other commands bound to `key` that may not share it with `command`. */
const findKeyConflicts = (
  command: string,
  key: string,
  keymap: KeyCommandKeymap | undefined
) =>
  KEY_COMMAND_ORDER.filter(
    (other) =>
      !mayShareKey(command, other, key) &&
      keysForCommand(other, keymap).some(
        (bound) => bound.toLowerCase() === key.toLowerCase()
      )
  );

type Modifier = "alt" | "ctrl" | "meta" | "mod" | "shift";

const MODIFIER_NAMES = new Map<string, Modifier>([
  ["alt", "alt"],
  ["cmd", "meta"],
  ["cmdorctrl", "mod"],
  ["command", "meta"],
  ["commandorcontrol", "mod"],
  ["control", "ctrl"],
  ["ctrl", "ctrl"],
  ["option", "alt"],
  ["shift", "shift"],
]);

const KEY_ALIASES = new Map([
  ["esc", "escape"],
  ["return", "enter"],
  ["space", " "],
]);

const IME_KEY_CODE = 229;

const isMacOS = () =>
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad/u.test(navigator.platform);

const isComposingKeyEvent = (event: KeyboardEvent) =>
  event.isComposing || event.keyCode === IME_KEY_CODE;

/** Whether the event is exactly the accelerator: same key and same modifiers. */
const matchesAccelerator = (event: KeyboardEvent, accelerator: string) => {
  const parts = accelerator.split("+");
  const keyName = (parts.pop() ?? "").toLowerCase();
  const wanted = { alt: false, ctrl: false, meta: false, shift: false };

  for (const part of parts) {
    const modifier = MODIFIER_NAMES.get(part.toLowerCase());

    if (modifier === "mod") {
      wanted[isMacOS() ? "meta" : "ctrl"] = true;
    } else if (modifier !== undefined) {
      wanted[modifier] = true;
    }
  }

  return (
    event.altKey === wanted.alt &&
    event.ctrlKey === wanted.ctrl &&
    event.metaKey === wanted.meta &&
    event.shiftKey === wanted.shift &&
    event.key.toLowerCase() === (KEY_ALIASES.get(keyName) ?? keyName)
  );
};

/* ---------------------------------------------------------------- registry */

interface Registration {
  handler: KeyCommandHandler;
  isActive: (context: KeyCommandContext) => boolean;
  priority: KeyCommandPriority;
}

/** Entry: what a registration tells menus and the keyboard-shortcut list. */
interface RegistrationInfo {
  composerId?: string;
  menuItem?: string;
}

type RegistrationSnapshot = ReadonlyMap<string, readonly RegistrationInfo[]>;

const PRIORITIES: readonly KeyCommandPriority[] = ["normal", "fallback"];

interface KeyCommandRegistry {
  /** Offers one keyboard event to the handlers of one command. */
  dispatchKeyboard: (
    commandId: string,
    event: KeyboardEvent,
    context?: KeyCommandContext
  ) => boolean;
  /** Runs the handlers of one command without an event. */
  dispatchCommand: (
    commandId: string,
    source: KeyCommandSource,
    context?: KeyCommandContext
  ) => boolean;
  /**
   * Offers a keyboard event to every command bound to its key, in table
   * order, and stops at the first command that accepts it. Prevented events
   * and IME composition are never offered, and an event is offered once.
   */
  dispatchEvent: (event: KeyboardEvent) => boolean;
  /**
   * Offers a keyboard event to one command only, whatever its binding. A form
   * that owns its keys uses this so a key it does not handle is never offered
   * to another command (an Enter in a composer must not approve a card). The
   * handlers decide from the event; a prevented key or an IME composition is
   * never offered, and an accepted event is prevented.
   */
  dispatchToCommand: (commandId: string, event: KeyboardEvent) => boolean;
  getSnapshot: () => RegistrationSnapshot;
  /** Whether any handler of the command is active. */
  hasActiveHandler: (commandId: string) => boolean;
  /** Returns the cleanup that removes this registration. */
  register: (
    commandId: string,
    handler: KeyCommandHandler,
    options?: KeyCommandOptions,
    info?: RegistrationInfo
  ) => () => void;
  setKeymap: (keymap: KeyCommandKeymap | undefined) => void;
  subscribe: (listener: () => void) => () => void;
}

const dispatchHandlers = (
  entries: readonly Registration[],
  source: KeyCommandSource,
  event: KeyboardEvent | undefined,
  context: KeyCommandContext
) => {
  for (const priority of PRIORITIES) {
    for (let index = entries.length - 1; index >= 0; index -= 1) {
      const entry = entries[index];

      if (
        entry?.priority === priority &&
        entry.isActive(context) &&
        entry.handler(source, event, context)
      ) {
        return true;
      }
    }
  }

  return false;
};

const withoutIndex = <Item,>(list: readonly Item[], index: number) =>
  list.filter((_, position) => position !== index);

const createKeyCommandRegistry = (): KeyCommandRegistry => {
  const handlers = new Map<string, Registration[]>();
  const listeners = new Set<() => void>();
  const offered = new WeakSet<Event>();
  let infos: RegistrationSnapshot = new Map();
  let keymap: KeyCommandKeymap | undefined;
  let registrations = 0;

  const publish = () => {
    for (const listener of listeners) {
      listener();
    }
  };

  const dispatchKeyboard = (
    commandId: string,
    event: KeyboardEvent,
    context?: KeyCommandContext
  ) =>
    dispatchHandlers(
      handlers.get(commandId) ?? [],
      "keyboard_shortcut",
      event,
      context
    );

  const dispatchEvent = (event: KeyboardEvent) => {
    if (
      event.defaultPrevented ||
      isComposingKeyEvent(event) ||
      event.repeat ||
      (isEditableTarget(event.target) &&
        !(event.ctrlKey || event.metaKey || event.altKey)) ||
      offered.has(event)
    ) {
      return false;
    }

    offered.add(event);

    for (const commandId of KEY_COMMAND_ORDER) {
      const bound = keysForCommand(commandId, keymap).some((key) =>
        matchesAccelerator(event, key)
      );

      if (bound && dispatchKeyboard(commandId, event)) {
        event.preventDefault();

        return true;
      }
    }

    return false;
  };

  const dispatchToCommand = (commandId: string, event: KeyboardEvent) => {
    if (event.defaultPrevented || isComposingKeyEvent(event)) {
      return false;
    }

    if (!dispatchKeyboard(commandId, event)) {
      return false;
    }

    event.preventDefault();

    return true;
  };

  const onWindowKeyDown = (event: KeyboardEvent) => {
    dispatchEvent(event);
  };

  const unregister = (commandId: string, entry: Registration) => {
    const current = handlers.get(commandId) ?? [];
    const index = current.lastIndexOf(entry);

    if (index === -1) {
      return;
    }

    const next = withoutIndex(current, index);

    if (next.length === 0) {
      handlers.delete(commandId);
    } else {
      handlers.set(commandId, next);
    }

    const remaining = withoutIndex(infos.get(commandId) ?? [], index);
    const copy = new Map(infos);

    if (remaining.length === 0) {
      copy.delete(commandId);
    } else {
      copy.set(commandId, remaining);
    }

    infos = copy;
    registrations -= 1;

    if (registrations === 0) {
      window.removeEventListener("keydown", onWindowKeyDown);
    }

    publish();
  };

  return {
    dispatchCommand: (commandId, source, context) =>
      dispatchHandlers(
        handlers.get(commandId) ?? [],
        source,
        undefined,
        context
      ),
    dispatchEvent,
    dispatchKeyboard,
    dispatchToCommand,
    getSnapshot: () => infos,
    hasActiveHandler: (commandId) =>
      handlers.get(commandId)?.some(({ isActive }) => isActive(undefined)) ??
      false,
    register: (commandId, handler, options = {}, info = {}) => {
      const entry: Registration = {
        handler,
        isActive: options.isActive ?? (() => true),
        priority: options.priority ?? "normal",
      };

      handlers.set(commandId, [...(handlers.get(commandId) ?? []), entry]);
      infos = new Map(infos).set(commandId, [
        ...(infos.get(commandId) ?? []),
        info,
      ]);
      registrations += 1;

      if (registrations === 1) {
        window.addEventListener("keydown", onWindowKeyDown);
      }

      publish();

      return () => {
        unregister(commandId, entry);
      };
    },
    setKeymap: (next) => {
      keymap = next;
    },
    subscribe: (listener) => {
      listeners.add(listener);

      return () => {
        listeners.delete(listener);
      };
    },
  };
};

/* ---------------------------------------------------------------- React */

/** Without a provider every consumer shares one registry, like the module-level map. */
const defaultRegistry = createKeyCommandRegistry();

const KeyCommandRegistryContext = createContext(defaultRegistry);

interface KeyCommandProviderProps {
  children?: ReactNode;
  /** Stored bindings that replace the defaults of the commands they name. */
  keymap?: KeyCommandKeymap;
}

/** Scopes a registry to a subtree, optionally with a remapped keymap. */
const KeyCommandProvider = ({ children, keymap }: KeyCommandProviderProps) => {
  // oxlint-disable-next-line react/hook-use-state -- The registry is created once for the provider and never replaced.
  const [registry] = useState(createKeyCommandRegistry);

  useLayoutEffect(() => {
    registry.setKeymap(keymap);
  }, [keymap, registry]);

  return (
    <KeyCommandRegistryContext.Provider value={registry}>
      {children}
    </KeyCommandRegistryContext.Provider>
  );
};

const useKeyCommandRegistry = () => useContext(KeyCommandRegistryContext);

const emptySnapshot: RegistrationSnapshot = new Map();

/** The live registrations by command id, as React state. */
const useKeyCommandRegistrations = (): RegistrationSnapshot => {
  const registry = useKeyCommandRegistry();

  return useSyncExternalStore(
    registry.subscribe,
    registry.getSnapshot,
    () => emptySnapshot
  );
};

interface UseKeyCommandOptions {
  composerId?: string;
  /** Runs for a non-keyboard invocation instead of the callback; `false` declines. */
  contextHandler?: (context: KeyCommandContext) => boolean | undefined;
  enabled?: boolean;
  isActive?: (context: KeyCommandContext) => boolean;
  /** Runs first for a keyboard event: `false` declines, `true` accepts without the callback. */
  keyboardHandler?: (
    event: KeyboardEvent,
    context: KeyCommandContext
  ) => boolean | undefined;
  menuItem?: string;
  priority?: KeyCommandPriority;
}

const noCleanup = () => {
  // There is nothing to undo while the command is disabled.
};

/**
 * Registers `callback` for `commandId` while `enabled`. The
 * latest callbacks are used without re-registering, so a registration keeps
 * its place in the newest-first order across renders.
 */
const useKeyCommand = (
  commandId: string,
  callback: (source: KeyCommandSource, context: KeyCommandContext) => void,
  {
    composerId,
    contextHandler,
    enabled = true,
    isActive,
    keyboardHandler,
    menuItem,
    priority = "normal",
  }: UseKeyCommandOptions = {}
) => {
  const registry = useKeyCommandRegistry();

  const latest = useRef({
    callback,
    contextHandler,
    isActive,
    keyboardHandler,
  });

  useLayoutEffect(() => {
    latest.current = { callback, contextHandler, isActive, keyboardHandler };
  });

  useEffect(() => {
    if (!enabled) {
      return noCleanup;
    }

    return registry.register(
      commandId,
      (source, event, context) => {
        const { current } = latest;

        const result =
          event === undefined
            ? undefined
            : current.keyboardHandler?.(event, context);

        if (result !== undefined) {
          return result;
        }

        if (current.contextHandler !== undefined) {
          return current.contextHandler(context) !== false;
        }

        current.callback(source, context);

        return true;
      },
      {
        isActive: (context) => latest.current.isActive?.(context) ?? true,
        priority,
      },
      { composerId, menuItem }
    );
  }, [commandId, composerId, enabled, menuItem, priority, registry]);
};

/**
 * For forms that own their keys and stop propagation, so the window never
 * sees them: returns a function that offers a keyboard event to `commandId`
 * only. It returns whether a handler accepted the event (which is then
 * prevented).
 */
const useKeyCommandDispatch = (commandId: KeyCommandId) => {
  const registry = useKeyCommandRegistry();

  return (event: KeyboardEvent) => registry.dispatchToCommand(commandId, event);
};

export {
  createKeyCommandRegistry,
  DEFAULT_KEYBINDINGS,
  findKeyConflicts,
  isComposingKeyEvent,
  KEY_COMMAND_ORDER,
  KeyCommandProvider,
  keysForCommand,
  matchesAccelerator,
  mayShareKey,
  useKeyCommand,
  useKeyCommandDispatch,
  useKeyCommandRegistrations,
  useKeyCommandRegistry,
};

export type {
  KeyBinding,
  KeyCommandContext,
  KeyCommandHandler,
  KeyCommandId,
  KeyCommandKeymap,
  KeyCommandOptions,
  KeyCommandPriority,
  KeyCommandProviderProps,
  KeyCommandRegistry,
  KeyCommandSource,
  RegistrationInfo,
  RegistrationSnapshot,
  UseKeyCommandOptions,
};

/*
 * Path geometry of the morphing send, stop and voice icon. Every shape is four closed paths of the
 * same command structure (one move and eight cubic curves each), so any two
 * shapes can be blended number by number. All coordinates are in a 20 by 20
 * viewBox.
 */

type Point = readonly [number, number];

type ComposerMorphState = "send" | "stop" | "voice";

/** The point `amount` of the way from `from` to `to`. */
const between = (from: Point, to: Point, amount: number): Point => [
  from[0] + (to[0] - from[0]) * amount,
  from[1] + (to[1] - from[1]) * amount,
];

const CIRCLE_HANDLE = (4 * (Math.SQRT2 - 1)) / 3;
const PATH_PRECISION = 3;
const VOICE_SCALE = 1.18;

/** Where a rounded corner starts and ends along its two edges. */
const corner = (
  previous: Point,
  vertex: Point,
  next: Point,
  radius: number
) => ({
  after: between(
    vertex,
    next,
    radius === 0
      ? 0
      : Math.min(
          0.5,
          radius / Math.hypot(next[0] - vertex[0], next[1] - vertex[1])
        )
  ),
  before: between(
    vertex,
    previous,
    radius === 0
      ? 0
      : Math.min(
          0.5,
          radius / Math.hypot(previous[0] - vertex[0], previous[1] - vertex[1])
        )
  ),
  vertex,
});

const fixed = (value: number) =>
  String(Number(value.toPrecision(PATH_PRECISION)));

/** A quadrilateral with rounded corners as one closed cubic path. */
const roundedQuad = (
  [first, second, third, fourth]: readonly [Point, Point, Point, Point],
  radius: number
) => {
  const corners = [
    corner(fourth, first, second, radius),
    corner(first, second, third, radius),
    corner(second, third, fourth, radius),
    corner(third, fourth, first, radius),
  ];

  const curves = corners.flatMap(({ after, before, vertex }) => [
    [before, before, before],
    [
      between(before, vertex, CIRCLE_HANDLE),
      between(after, vertex, CIRCLE_HANDLE),
      after,
    ],
  ]);

  const [startX, startY] = corners[3].after;

  return `M${fixed(startX)} ${fixed(startY)} ${curves
    .map((curve) => `C${curve.flat().map(fixed).join(" ")}`)
    .join(" ")} Z`;
};

/** A rounded rectangle. */
const roundedRect = (
  x: number,
  y: number,
  width: number,
  height: number,
  radius: number
) =>
  roundedQuad(
    [
      [x, y],
      [x + width, y],
      [x + width, y + height],
      [x, y + height],
    ],
    radius
  );

/** A line with the given thickness and half-thickness corner radius. */
const capsule = (start: Point, end: Point, thickness: number) => {
  const length = Math.hypot(end[0] - start[0], end[1] - start[1]);

  const side: Point = [
    (((end[1] - start[1]) / length) * thickness) / 2,
    (((start[0] - end[0]) / length) * thickness) / 2,
  ];

  const along: Point = [-side[1], side[0]];

  return roundedQuad(
    [
      [start[0] - side[0] - along[0], start[1] - side[1] - along[1]],
      [start[0] + side[0] - along[0], start[1] + side[1] - along[1]],
      [end[0] + side[0] + along[0], end[1] + side[1] + along[1]],
      [end[0] - side[0] + along[0], end[1] - side[1] + along[1]],
    ],
    thickness / 2
  );
};

/** Scale bar offsets around the center of the 20 by 20 viewBox. */
const bars = (
  scale: number,
  thickness: number,
  rows: readonly (readonly [number, number, number])[]
) =>
  rows.map(([x, y1, y2]) =>
    capsule(
      [10 + x * scale, 10 + y1 * scale],
      [10 + x * scale, 10 + y2 * scale],
      thickness * scale
    )
  );

/** A zero-size shape at the centre, the resting place of an unused path. */
const UNUSED_PATH = roundedRect(10, 10, 0, 0, 0);

const MORPH_PATHS = {
  send: [
    capsule([10, 4.6], [10, 16.7], 1.4),
    capsule([4.17, 9.17], [10, 3.33], 1.4),
    capsule([10, 3.33], [15.8, 9.17], 1.4),
    UNUSED_PATH,
  ],
  stop: [
    roundedRect(4.7, 4.7, 10.6, 10.6, 1.2),
    UNUSED_PATH,
    UNUSED_PATH,
    UNUSED_PATH,
  ],
  voice: bars(VOICE_SCALE, 1.4, [
    [-1.6, -5.2, 5.2],
    [-4.8, 1.8, -1.8],
    [1.6, -3.2, 3.2],
    [4.8, -1.3, 1.3],
  ]),
} as const satisfies Record<ComposerMorphState, readonly string[]>;

/** The voice bars collapsed to a short column, the middle of a voice morph. */
const VOICE_COLLAPSED = bars(VOICE_SCALE, 1.1, [
  [0, -4.6, 4.6],
  [-2.3, 1.5, -1.5],
  [1.4, -2.6, 2.6],
  [2.6, -1.05, 1.05],
]);

/** The send shapes drawn as one vertical line each, the other middle of a voice morph. */
const VOICE_SEND_LINES = [
  capsule([10, 3.33], [10, 16.7], 1.4),
  capsule([10, 9.17], [10, 3.33], 1.4),
  capsule([10, 3.33], [10, 9.17], 1.4),
  UNUSED_PATH,
];

export { UNUSED_PATH, MORPH_PATHS, VOICE_COLLAPSED, VOICE_SEND_LINES };

export type { ComposerMorphState };

"use client";

import { cn } from "@/lib/utils";
import { useSyncExternalStore } from "react";
import type { ComponentProps } from "react";

import styles from "@/components/composer/composer.module.css";

/** Draws the overlay material with CSS. A host layer can replace it through the data-ck-overlay-* attributes. */

const CK_OVERLAY_ROUTE = "/ck-overlay";

/** The pathname, or the initialRoute query value without its own query, is the overlay window. */
const isAvatarOverlayLocation = ({
  initialRoute,
  pathname,
}: {
  initialRoute: string | null;
  pathname: string;
}) =>
  pathname === CK_OVERLAY_ROUTE ||
  initialRoute?.split("?")[0] === CK_OVERLAY_ROUTE;

/** The location the test reads; empty without a window. */
const readLocation = () => {
  if (typeof window === "undefined") {
    return { initialRoute: null, pathname: "" };
  }

  const url = new URL(window.location.href);

  return {
    initialRoute: url.searchParams.get("initialRoute"),
    pathname: url.pathname,
  };
};

const subscribeToLocation = (onChange: () => void) => {
  window.addEventListener("popstate", onChange);

  return () => {
    window.removeEventListener("popstate", onChange);
  };
};

/** True on the overlay window. Server and first client render say false. */
const useIsAvatarOverlay = () =>
  useSyncExternalStore(
    subscribeToLocation,
    () => isAvatarOverlayLocation(readLocation()),
    () => false
  );

type AvatarOverlayMaterialTone = string;

interface AvatarOverlayMaterialProps extends ComponentProps<"div"> {
  nativeSurfaceId?: string;
  tone?: AvatarOverlayMaterialTone;
  /** Falls back to `nativeSurfaceId`. */
  variant?: string;
}

/** A div with the material class and the overlay material attributes. */
const AvatarOverlayMaterial = ({
  className,
  nativeSurfaceId,
  tone,
  variant,
  ...props
}: AvatarOverlayMaterialProps) => {
  const isQuickChat = variant === "quick" || variant === "quick-stash";

  return (
    <div
      {...props}
      className={cn(
        styles.material,
        isQuickChat && styles.quickChatMaterial,
        className
      )}
      data-ck-overlay-compact-tone={tone}
      data-ck-overlay-material="css"
      data-ck-overlay-variant={variant ?? nativeSurfaceId}
      data-ck-overlay-native-surface-id={nativeSurfaceId}
    />
  );
};

export { AvatarOverlayMaterial, isAvatarOverlayLocation, useIsAvatarOverlay };

export type { AvatarOverlayMaterialProps, AvatarOverlayMaterialTone };

"use client";

import { AppLink } from "@/components/list/app-link";
import {
  ExternalResourcePolicyContext,
  LinkProviderContext,
} from "@/components/markdown/external-link";
import type {
  ExternalResourcePolicy,
  LinkProviderRenderOptions,
} from "@/components/markdown/external-link";
import { TEXT_LINK_CLASSES } from "@/components/ui/markdown";
import { InlineMention } from "@/components/ui/mention";
import { isValidElement, useContext } from "react";
import type { ComponentProps, ComponentType, ReactNode } from "react";

/*
 * The link inside an approval reason draws AppLink around the mention
 * family's InlineMention, with the URL as its tooltip. A link provider set by
 * the host receives the href and a render function, and decides on a preview
 * card, a custom icon or tooltip. A restricted resource policy, from the
 * prop or an ancestor, makes the link ask before it opens.
 */

type ReasonLinkAppearance = "decorated" | "inline-mention" | "underlined-text";

type AppLinkComponent = ComponentType<ComponentProps<typeof AppLink>>;

interface ApprovalReasonLinkProps {
  /** How the link renders, default `inline-mention`. */
  appearance?: ReasonLinkAppearance;
  children?: ReactNode;
  conversationId?: string | null;
  /** The external link component, default the app link. */
  ExternalLinkComponent?: AppLinkComponent;
  /** The external resource policy, default `allow`. */
  externalResourcePolicy?: ExternalResourcePolicy;
  href?: string;
  isBrowserEnabled?: boolean;
  openTarget?: ComponentProps<typeof AppLink>["openTarget"];
  originHostId?: string;
  services?: ComponentProps<typeof AppLink>["services"];
  title?: string;
}

/** The host effect that opens a link; without a host the page opens it in a new tab. */
const DEFAULT_SERVICES: ComponentProps<typeof AppLink>["services"] = {
  onOpenLink: ({ href }) => {
    window.open(href, "_blank", "noopener,noreferrer");
  },
};

interface ReasonLinkBodyProps extends Omit<
  ApprovalReasonLinkProps,
  "externalResourcePolicy" | "href"
> {
  href: string;
  options?: LinkProviderRenderOptions;
  policy: ExternalResourcePolicy;
}

const ReasonLinkBody = ({
  appearance = "inline-mention",
  children,
  conversationId,
  ExternalLinkComponent: Link = AppLink,
  href,
  isBrowserEnabled,
  openTarget,
  options,
  originHostId,
  policy,
  services = DEFAULT_SERVICES,
  title,
}: ReasonLinkBodyProps) => {
  const decorated = appearance === "decorated";
  const tooltip = options?.customTooltip ?? (decorated ? undefined : href);

  const content =
    decorated && !isValidElement(options?.customIcon) ? (
      children
    ) : (
      <InlineMention
        appearance={decorated ? "inline-mention" : appearance}
        icon={
          isValidElement<{ className?: string }>(options?.customIcon)
            ? options.customIcon
            : undefined
        }
        underlineOnHover={appearance !== "underlined-text"}
      >
        {children}
      </InlineMention>
    );

  return (
    <Link
      className={TEXT_LINK_CLASSES}
      contextMenuInitiator="link_menu"
      conversationId={conversationId}
      data-ck-inline-mention-interactive=""
      href={href}
      initiator="link_click"
      isBrowserEnabled={isBrowserEnabled}
      openTarget={openTarget}
      originHostId={originHostId}
      requiresConfirmation={policy === "restricted"}
      services={services}
      title={title}
      tooltipContent={tooltip}
      tooltipDelayDuration={options?.tooltipDelayDuration}
    >
      {content}
    </Link>
  );
};

/** No href renders the children as they are. */
// oxlint-disable-next-line typescript/promise-function-async -- the component returns its children as they are, which the ReactNode type allows to be a promise
const ApprovalReasonLink = ({
  children,
  externalResourcePolicy,
  href,
  ...props
}: ApprovalReasonLinkProps) => {
  const inherited = useContext(ExternalResourcePolicyContext);
  const Provider = useContext(LinkProviderContext);

  if (href === undefined || href === "") {
    return children;
  }

  const policy: ExternalResourcePolicy =
    externalResourcePolicy === "restricted" || inherited === "restricted"
      ? "restricted"
      : "allow";

  const render = (options?: LinkProviderRenderOptions) => (
    <ReasonLinkBody {...props} href={href} options={options} policy={policy}>
      {children}
    </ReasonLinkBody>
  );

  // oxlint-disable-next-line react/static-components -- the provider is a component the host sets in context, not one made here
  return Provider ? <Provider href={href}>{render}</Provider> : render();
};

export { ApprovalReasonLink };

export type { ApprovalReasonLinkProps, ReasonLinkAppearance };

/* oxlint-disable anti-slop/no-unknown-parameters -- A thrown value is untyped; the component reads its code and size by shape. */

/*
 * The rules of the main composer that do not depend on its ProseMirror
 * editor and the modules it imports:
 *
 * - queueing and the follow-up shortcut,
 * - send rules: the submit, steer, queue and clear commands and the Enter
 *   behaviour,
 * - placeholders, including the working placeholder,
 * - attachments: the draft dedupe key, the upload messages, the pasted-text
 *   limit and the undo entry.
 *
 * Strings are the default English messages.
 */

/* ---------------------------------------------------------------- queueing */

type FollowUpQueueMode = "queue" | "steer";

/** The stored value may still be the retired `interrupt`. */
type StoredFollowUpQueueMode = FollowUpQueueMode | "interrupt" | undefined;

interface FollowUpQueueState {
  isQueueingEnabled: boolean;
  mode: FollowUpQueueMode;
  /** True when the stored `interrupt` has to be rewritten to `steer`. */
  needsMigration: boolean;
}

/**
 * use-follow-up-queue-mode: `interrupt` reads as `steer` (and is stored as
 * `steer`), no stored value reads as `queue`, and queueing is on in `queue`.
 */
const resolveFollowUpQueueMode = (
  stored: StoredFollowUpQueueMode
): FollowUpQueueState => {
  const mode: FollowUpQueueMode =
    stored === "interrupt" ? "steer" : (stored ?? "queue");

  return {
    isQueueingEnabled: mode === "queue",
    mode,
    needsMigration: stored === "interrupt",
  };
};

type ComposerEnterBehavior = "cmdAlways" | "cmdIfMultiline" | "enter";

type FollowUpSubmitAction = "queue" | "steer";

interface FollowUpShortcutEvent {
  altKey: boolean;
  ctrlKey: boolean;
  metaKey: boolean;
  repeat: boolean;
  shiftKey: boolean;
}

interface FollowUpShortcutState {
  canQueueFollowUp: boolean;
  enterBehavior: ComposerEnterBehavior;
  event: FollowUpShortcutEvent;
  followUpType: string | undefined;
  isQueueingEnabledForCurrentFollowUp: boolean;
  isResponseInProgress: boolean;
}

type FollowUpShortcutResult =
  | { action: FollowUpSubmitAction; kind: "submit" }
  | { kind: "ignore" }
  | { kind: "swallow" };

/**
 * The modified Enter while a response is in progress. A repeated
 * Cmd/Ctrl+Enter is swallowed. With enter behaviour `enter` the key is
 * Cmd/Ctrl+Enter, otherwise Cmd/Ctrl+Shift+Enter; it only acts on a local
 * follow-up with a response in progress. It does the opposite of the current
 * default: steer when queueing is on or cannot be used, queue otherwise.
 */
const resolveFollowUpShortcut = ({
  canQueueFollowUp,
  enterBehavior,
  event,
  followUpType,
  isQueueingEnabledForCurrentFollowUp,
  isResponseInProgress,
}: FollowUpShortcutState): FollowUpShortcutResult => {
  const modified = event.metaKey || event.ctrlKey;

  if (event.repeat && modified && !event.shiftKey && !event.altKey) {
    return { kind: "swallow" };
  }

  const matches =
    enterBehavior === "enter"
      ? modified && !event.shiftKey && !event.altKey
      : modified && event.shiftKey && !event.altKey;

  if (!matches || followUpType !== "local" || !isResponseInProgress) {
    return { kind: "ignore" };
  }

  return {
    action:
      !canQueueFollowUp || isQueueingEnabledForCurrentFollowUp
        ? "steer"
        : "queue",
    kind: "submit",
  };
};

/* ---------------------------------------------------------------- send rules */

interface EnterSubmitEvent {
  altKey: boolean;
  ctrlKey: boolean;
  key: string;
  metaKey: boolean;
  shiftKey: boolean;
  target: EventTarget | null;
}

const INTERACTIVE_ENTER_TARGETS = "button, a[href], select, [role='button']";

/**
 * Cmd/Ctrl+Enter always submits; a bare Enter submits when the Enter
 * behaviour is `enter`, or `cmdIfMultiline` while the text is a single line,
 * and the focus is not on a button, link, select or role=button.
 */
const submitsOnEnter = (
  event: EnterSubmitEvent,
  enterBehavior: ComposerEnterBehavior,
  isMultiline: boolean,
  activeElement: Element | null
) => {
  if (event.key !== "Enter" || event.altKey) {
    return false;
  }

  const modified = event.metaKey || event.ctrlKey;

  if (modified && !event.shiftKey) {
    return true;
  }

  const bareEnterSubmits =
    enterBehavior === "enter" ||
    (enterBehavior === "cmdIfMultiline" && !isMultiline);

  return (
    bareEnterSubmits &&
    !modified &&
    !event.shiftKey &&
    (activeElement?.closest(INTERACTIVE_ENTER_TARGETS) ?? null) === null
  );
};

type SubmitButtonMode = "stop" | "submit";

interface SendCommandState {
  composerInteractionsEnabled: boolean;
  isDictating: boolean;
  isResumePending: boolean;
  submitButtonMode: SubmitButtonMode;
  submitDisabled: boolean;
}

interface SendCommandAvailability {
  /** composer.resetDraft */
  clear: boolean;
  /** composer.enqueueMessage and composer.redirectRun */
  followUp: boolean;
  /** composer.sendMessage */
  submit: boolean;
}

/** When each command is registered. Dictation counts as something to send. */
const sendCommandAvailability = ({
  composerInteractionsEnabled,
  isDictating,
  isResumePending,
  submitButtonMode,
  submitDisabled,
}: SendCommandState): SendCommandAvailability => {
  const live = composerInteractionsEnabled && !isResumePending;

  return {
    clear: composerInteractionsEnabled,
    followUp:
      live && !isDictating && !submitDisabled && submitButtonMode === "submit",
    submit: live && (isDictating || !submitDisabled),
  };
};

type SubmitCommandOutcome = "ignored" | "stop-dictation" | "submit";

/**
 * The composer.sendMessage handler: while dictating it sends the dictation, with
 * nothing to send it does nothing, and in `stop` mode it does not submit.
 */
const resolveSubmitCommand = ({
  composerInteractionsEnabled,
  isDictating,
  isResumePending,
  submitButtonMode,
  submitDisabled,
}: SendCommandState): SubmitCommandOutcome => {
  if (!composerInteractionsEnabled || isResumePending) {
    return "ignored";
  }

  if (isDictating) {
    return "stop-dictation";
  }

  return !submitDisabled && submitButtonMode === "submit"
    ? "submit"
    : "ignored";
};

/* ---------------------------------------------------------------- placeholders */

type ComposerProductMode = "chat" | "code" | "work";

const PLACEHOLDER_WORKING = "Working…";
const PLACEHOLDER_IMAGE_MARKUP = "Add instructions…";

const PLACEHOLDER_GOAL = "Describe your goal and the outcomes you want";

const PLACEHOLDER_PLAN = "Describe your task to generate a plan...";
const PLACEHOLDER_ASK_ASSISTANT = "Ask the assistant";
const PLACEHOLDER_WORK_WITH_AGENT = "Work with the agent";
const PLACEHOLDER_DO_ANYTHING = "Do anything";
const PLACEHOLDER_WORK_WITH_ASSISTANT = "Work with the assistant";
const PLACEHOLDER_THINKING = "Thinking…";

/** The product placeholder. A workspace agent name replaces the chat text. */
const productPlaceholder = (
  productMode: ComposerProductMode,
  {
    isFollowUp = false,
    workspaceAgentName,
  }: {
    isFollowUp?: boolean;
    workspaceAgentName?: string;
  } = {}
) => {
  switch (productMode) {
    case "chat": {
      return workspaceAgentName === undefined
        ? PLACEHOLDER_ASK_ASSISTANT
        : `Ask ${workspaceAgentName}`;
    }

    case "code": {
      return isFollowUp ? PLACEHOLDER_WORK_WITH_AGENT : PLACEHOLDER_DO_ANYTHING;
    }

    case "work": {
      return PLACEHOLDER_WORK_WITH_ASSISTANT;
    }

    default: {
      return PLACEHOLDER_DO_ANYTHING;
    }
  }
};

interface ComposerPlaceholderState {
  /** Set when the composer continues a chat. */
  followUpType?: string | null;
  isCompactFloatingComposer?: boolean;
  isGoalModeActive?: boolean;
  isImageMarkupActive?: boolean;
  isPlanModeActive?: boolean;
  isResponseInProgress?: boolean;
  /** A caller supplied text wins over the product text. */
  placeholderText?: string | null;
  productMode: ComposerProductMode;
}

/**
 * The first match wins. Image markup, a compact floating composer with a
 * response in progress, goal mode, plan mode, the caller's text, then the
 * product placeholder (a follow-up when `followUpType` is not null).
 */
const composerPlaceholder = ({
  followUpType,
  isCompactFloatingComposer = false,
  isGoalModeActive = false,
  isImageMarkupActive = false,
  isPlanModeActive = false,
  isResponseInProgress = false,
  placeholderText,
  productMode,
}: ComposerPlaceholderState) => {
  if (isImageMarkupActive) {
    return PLACEHOLDER_IMAGE_MARKUP;
  }

  if (isCompactFloatingComposer && isResponseInProgress) {
    return PLACEHOLDER_WORKING;
  }

  if (isGoalModeActive) {
    return PLACEHOLDER_GOAL;
  }

  if (isPlanModeActive) {
    return PLACEHOLDER_PLAN;
  }

  return (
    placeholderText ??
    productPlaceholder(productMode, {
      isFollowUp: followUpType !== undefined && followUpType !== null,
    })
  );
};

interface WorkingComposerState<Heading> {
  /** The latest work heading, or null while there is none. */
  heading: Heading | null;
  /** Whether the thread is loading, read and not blocked, worked out by the caller. */
  isLoadingWithoutBlocker: boolean;
  placeholder: string;
}

interface WorkingComposerResult<Heading> {
  accessibleStatus: Heading | string | null;
  /** True when the heading row replaces the placeholder. */
  showsWorkingHeading: boolean;
  placeholder: string;
}

/**
 * While the floating composer has a work heading, or is loading without a
 * blocking request, the placeholder is empty, the heading row shows and the
 * accessible status is the heading, or "Thinking…" when there is none.
 */
const workingComposerState = <Heading>({
  heading,
  isLoadingWithoutBlocker,
  placeholder,
}: WorkingComposerState<Heading>): WorkingComposerResult<Heading> => {
  const showsWorkingHeading = heading !== null || isLoadingWithoutBlocker;

  return {
    accessibleStatus: showsWorkingHeading
      ? (heading ?? PLACEHOLDER_THINKING)
      : null,
    placeholder: showsWorkingHeading ? "" : placeholder,
    showsWorkingHeading,
  };
};

/* ---------------------------------------------------------------- attachments */

interface FileAttachmentRef {
  endLine?: number;
  fsPath: string;
  startLine?: number;
}

/** composer-attachment-actions K: the key that makes two file attachments the same. */
const fileAttachmentKey = ({ endLine, fsPath, startLine }: FileAttachmentRef) =>
  JSON.stringify([fsPath, startLine, endLine]);

/** Drops attachments already in the draft and repeats inside the new batch. */
const dedupeFileAttachments = <Attachment extends FileAttachmentRef>(
  existing: readonly FileAttachmentRef[],
  incoming: readonly Attachment[]
): Attachment[] => {
  const seen = new Set(existing.map(fileAttachmentKey));

  return incoming.filter((attachment) => {
    const key = fileAttachmentKey(attachment);

    if (seen.has(key)) {
      return false;
    }

    seen.add(key);

    return true;
  });
};

const BYTES_PER_MEGABYTE = 1_048_576;

const FILE_UPLOAD_ERROR_MESSAGE = "Unable to upload file";

const REMOTE_FOLDER_UNSUPPORTED_MESSAGE =
  "Folders can only be attached to local conversations";

const BROWSER_FILE_COPY_ERROR_MESSAGE = "Unable to attach file";
const IMAGE_UPLOAD_FAILED_MESSAGE = "Failed to upload image";
const ATTACHMENT_RESTORED_MESSAGE = "Attachment restored";

/** composer-attachment-actions K (second function): the too-large error carries its limit. */
const isFileTooLargeError = (
  error: unknown
): error is Error & {
  code: "attachment_too_large";
  maximumSizeBytes: number;
} =>
  error instanceof Error &&
  "code" in error &&
  error.code === "attachment_too_large" &&
  "maximumSizeBytes" in error &&
  typeof error.maximumSizeBytes === "number";

/** composer-attachment-actions he: the toast text of a failed remote upload. */
const fileUploadErrorMessage = (error: unknown) =>
  isFileTooLargeError(error)
    ? `File is too large to upload (maximum ${new Intl.NumberFormat("en-US").format(error.maximumSizeBytes / BYTES_PER_MEGABYTE)} MB)`
    : FILE_UPLOAD_ERROR_MESSAGE;

/** pasted-text-file-attachment-actions f: a pasted text attachment longer than this is not restored. */
const PASTED_TEXT_RESTORE_LIMIT = 25_000;

const canRestorePastedText = (text: string) =>
  text.length <= PASTED_TEXT_RESTORE_LIMIT;

/** How long an undo entry stays available. */
const ATTACHMENT_UNDO_WINDOW_MS = 60_000;

export {
  ATTACHMENT_RESTORED_MESSAGE,
  ATTACHMENT_UNDO_WINDOW_MS,
  BROWSER_FILE_COPY_ERROR_MESSAGE,
  canRestorePastedText,
  composerPlaceholder,
  dedupeFileAttachments,
  FILE_UPLOAD_ERROR_MESSAGE,
  fileAttachmentKey,
  fileUploadErrorMessage,
  IMAGE_UPLOAD_FAILED_MESSAGE,
  isFileTooLargeError,
  PASTED_TEXT_RESTORE_LIMIT,
  PLACEHOLDER_THINKING,
  productPlaceholder,
  REMOTE_FOLDER_UNSUPPORTED_MESSAGE,
  resolveFollowUpQueueMode,
  resolveFollowUpShortcut,
  resolveSubmitCommand,
  sendCommandAvailability,
  submitsOnEnter,
  workingComposerState,
};

export type {
  ComposerEnterBehavior,
  ComposerPlaceholderState,
  ComposerProductMode,
  EnterSubmitEvent,
  FileAttachmentRef,
  FollowUpQueueMode,
  FollowUpQueueState,
  FollowUpShortcutEvent,
  FollowUpShortcutResult,
  FollowUpShortcutState,
  FollowUpSubmitAction,
  SendCommandAvailability,
  SendCommandState,
  StoredFollowUpQueueMode,
  SubmitButtonMode,
  SubmitCommandOutcome,
  WorkingComposerResult,
  WorkingComposerState,
};

/* oxlint-disable eslint/max-classes-per-file, unicorn/custom-error-definition, anti-slop/no-unknown-parameters, anti-slop/no-runtime-typeof, anti-slop/require-safety-comment-for-type-assertion -- Thrown values are untyped; the component reads their message, data.code and detail by shape. */

import type { ToastManager } from "@/components/toast/manager";
import type { ReactNode } from "react";

/*
 * Submit-failure messages: the toast
 * text chosen for an error: one for a local task, one for the rest, two for
 * cloud submissions and three for specific cases. Each message is its default
 * English text and
 * `{br}` is a line break element.
 */

type ComposerSubmitMode = string;

interface SubmitErrorEnvelope {
  message: string;
  type: string | null;
}

const APP_INPUT_ERROR = "Could not use app content";
const APP_INPUT_MESSAGE = "Content from the app could not be used";
const MISSING_GITHUB_CONNECTOR_LINK = "github_link_missing";
const BROWSER_TAB_MENTION_LIMIT = 100;
const WORKTREE_INIT_FAILED = "worktree_setup_error";
const CLOSED_AGENT_MARKER = "agent_closed";

/** The message text of any thrown value. */
const errorMessage = (error: unknown): string => {
  if (error instanceof Error) {
    return error.message;
  }

  if (typeof error === "string") {
    return error;
  }

  if (typeof error === "object" && error !== null && "message" in error) {
    const { message } = error as { message?: unknown };

    if (typeof message === "string" && message.length > 0) {
      return message;
    }
  }

  try {
    return JSON.stringify(error);
  } catch {
    return String(error);
  }
};

/** The `detail` of a JSON error body, normalised to a type and a message. */
const parseErrorDetail = (error: Error): SubmitErrorEnvelope | null => {
  try {
    const body: unknown = JSON.parse(error.message);

    if (typeof body !== "object" || body === null || !("detail" in body)) {
      return null;
    }

    const { detail } = body;

    if (typeof detail === "string") {
      return { message: detail, type: null };
    }

    if (typeof detail !== "object" || detail === null) {
      return null;
    }

    const {
      error_code: code,
      message,
      type,
    } = detail as {
      error_code?: unknown;
      message?: unknown;
      type?: unknown;
    };

    if (typeof message !== "string") {
      return null;
    }

    let kind: string | null = null;

    if (typeof type === "string") {
      kind = type;
    } else if (typeof code === "string") {
      kind = code;
    }

    return { message, type: kind };
  } catch {
    return null;
  }
};

const lineBreak = (message: string, error: string, key: string): ReactNode => (
  <>
    {message}
    <br key={key} />
    {error}
  </>
);

const threadReferenceMessage = (error: unknown) =>
  errorMessage(error) === "thread_refs_missing"
    ? "Remove the chat references, or use them in a new chat instead"
    : null;

const browserTabMentionMessage = (error: unknown) => {
  switch (errorMessage(error)) {
    case "tab_context_overflow": {
      return "Remove some browser tab mentions before sending this message again";
    }

    case "tab_count_overflow": {
      return `You can mention up to ${BROWSER_TAB_MENTION_LIMIT} browser tabs per message`;
    }

    default: {
      return null;
    }
  }
};

const worktreeStateMessage = (error: unknown) => {
  const text = errorMessage(error);

  if (text.includes("worktree_needs_restore")) {
    return "Restore this worktree before continuing";
  }

  if (text.includes("worktree_gone")) {
    return "This worktree has been removed";
  }

  if (text.includes("worktree_state_unknown")) {
    return "The worktree status could not be read";
  }

  return null;
};

/** A worktree setup script failure carries `data.code`. */
const isWorktreeSetupFailure = (error: unknown) => {
  if (typeof error !== "object" || error === null || !("data" in error)) {
    return false;
  }

  const { data } = error;

  return (
    typeof data === "object" &&
    data !== null &&
    "code" in data &&
    data.code === WORKTREE_INIT_FAILED
  );
};

const WORKTREE_SETUP_FAILED =
  "The worktree setup script failed. Review the script in the host environment settings";

/** Messages for the first or follow-up message of a code task and for cloud task creation. */
const cloudSubmitMessage = (error: unknown, creation: boolean): ReactNode => {
  if (errorMessage(error) === APP_INPUT_ERROR) {
    return APP_INPUT_MESSAGE;
  }

  const detail = error instanceof Error ? parseErrorDetail(error) : null;

  if (detail?.type === MISSING_GITHUB_CONNECTOR_LINK) {
    return "Reconnect GitHub in Plugins before sending this request";
  }

  return lineBreak(
    "The message could not be sent",
    detail?.message ?? errorMessage(error),
    creation ? "remote-submit-error-detail" : "submit-error-detail"
  );
};

/** The message for a failed worktree or local submission. */
const localSubmitMessage = (error: unknown): ReactNode => {
  if (errorMessage(error) === APP_INPUT_ERROR) {
    return APP_INPUT_MESSAGE;
  }

  return (
    threadReferenceMessage(error) ??
    browserTabMentionMessage(error) ??
    worktreeStateMessage(error) ??
    (isWorktreeSetupFailure(error)
      ? WORKTREE_SETUP_FAILED
      : lineBreak(
          "Error starting chat",
          errorMessage(error),
          "local-task-error-break"
        ))
  );
};

/**
 * The message for the modes other than worktree. The thread
 * reference, browser tab and worktree state messages come first, then a worktree
 * setup failure (worktree mode only), a closed sub-agent chat (the error text
 * contains `agent_closed`), and the cloud or other task message.
 */
const composerSubmitErrorMessage = (
  error: unknown,
  mode: ComposerSubmitMode
): ReactNode => {
  const specific =
    threadReferenceMessage(error) ??
    browserTabMentionMessage(error) ??
    worktreeStateMessage(error);

  if (specific !== null) {
    return specific;
  }

  if (mode === "worktree" && isWorktreeSetupFailure(error)) {
    return WORKTREE_SETUP_FAILED;
  }

  if (errorMessage(error).includes(CLOSED_AGENT_MARKER)) {
    return "Resume this sub-agent from its parent conversation before replying";
  }

  return cloudSubmitMessage(error, mode === "cloud");
};

/**
 * A failed submit uses the message for its mode.
 * The composer stays populated so the user can retry.
 */
const submitFailureMessage = (
  error: unknown,
  mode: ComposerSubmitMode
): ReactNode =>
  mode === "worktree"
    ? localSubmitMessage(error)
    : composerSubmitErrorMessage(error, mode);

/* ---------------------------------------------------------------- failure handler */

/** An error that carries its own user-facing message. */
class ComposerSubmitError extends Error {}

/** A slide suggestion was sent in Cloud mode. */
class PresentationSuggestionCloudUnsupportedError extends Error {}

/** A reply-chain draft that includes images. */
class ReplyTextOnlyError extends Error {
  constructor() {
    super("reply_text_mode");
  }
}

/** The app request error with its delivery flags. */
class AppRequestError extends Error {
  deliveryUnknown: boolean;
  retryWithSameRequest: boolean;
  status: number | undefined;

  constructor(
    message: string,
    status?: number,
    options?: { deliveryUnknown?: boolean; retryWithSameRequest?: boolean }
  ) {
    super(message);
    this.status = status;
    this.deliveryUnknown = options?.deliveryUnknown ?? false;
    this.retryWithSameRequest = options?.retryWithSameRequest ?? false;
  }
}

/** The project context could not be synced. The handler ignores it. */
class ProjectContextSyncError extends Error {
  constructor() {
    super("Could not sync project context");
  }
}

/** The user cancelled the follow-up confirmation dialog. The handler ignores it. */
class FollowUpConfirmationCancelledError extends Error {}

/** The app HTTP error with a status and an error code. */
class AppHttpError extends Error {
  errorCode: string | undefined;
  status: number;

  constructor(message: string, status: number, errorCode?: string) {
    super(message);
    this.status = status;
    this.errorCode = errorCode;
  }
}

/** A predicate on any value, not an error class. */
const isModelUnavailable = (
  error: unknown
): error is Error & { code: "model-unavailable" } =>
  error instanceof Error &&
  "code" in error &&
  error.code === "model-unavailable";

/** The assistant's chosen name failed moderation. */
const isRejectedNameError = (error: unknown) =>
  error instanceof AppHttpError &&
  error.status === 400 &&
  error.errorCode === "invalid_name";

const NAME_REJECTED_MESSAGE =
  "This name is not allowed. Choose a different name.";

const PRESENTATION_SUGGESTION_CLOUD_MESSAGE =
  "To send this slide suggestion, leave Cloud mode or remove the slide attachment";

const REPLY_TEXT_ONLY_MESSAGE =
  "Remove the images before replying. Replies accept only text.";

const VIEW_DIAGNOSTICS_LABEL = "View diagnostics";

/** Toast ids of the handler. */
const COMPOSER_TASK_ERROR_TOAST_ID = "composer.taskError";

/** The error analytics payload every failure toast carries. */
const COMPOSER_SUBMIT_ERROR_ANALYTICS = {
  code: "submit_failed",
  source: "composer",
  surface: "toast",
} as const;

/** What the failure handler gives the diagnostics host; the host classifies, redacts and normalises it (components/composer/diagnostics-host.ts). */
interface SubmitDiagnosticsReport {
  conversationId: string | null;
  errorMessage: string;
  occurredAtMs: number;
  operation: string;
  surface: "code";
}

/**
 * The host's diagnostics service. It returns no action when the
 * diagnostics gate is off. Otherwise it prepares the report once, when the
 * failure happens, and returns the handler that the "View diagnostics" action
 * runs on click.
 */
interface SubmitDiagnosticsHost {
  prepare: (report: SubmitDiagnosticsReport) => (() => void) | undefined;
}

interface SubmitFailureOptions {
  composerMode: ComposerSubmitMode;
  conversationId?: string | null;
  cwd?: string | null;
  /** Diagnostics service, kept apart from the analytics payload. */
  diagnostics?: SubmitDiagnosticsHost;
  followUpType?: string;
  /** Logger o.error. */
  log?: (
    message: string,
    details: {
      safe: { followUp: string | undefined; mode: ComposerSubmitMode };
      sensitive: { cwd: string | null | undefined; error: unknown };
    }
  ) => void;
  now?: () => number;
  toast: ToastManager;
}

/** The "View diagnostics" toast action, or nothing when the host has none. */
const viewDiagnosticsAction = (
  diagnostics: SubmitDiagnosticsHost | undefined,
  report: SubmitDiagnosticsReport
) => {
  const onClick = diagnostics?.prepare(report);

  return onClick === undefined
    ? undefined
    : { label: VIEW_DIAGNOSTICS_LABEL, onClick };
};

/**
 * The failure handler of the composer submit. It returns what
 * `(error, toastId, operation)` does: a rejected name, a Cloud slide
 * suggestion, a text-only reply and an error that carries its own message each
 * show their toast and stop; project-sync, cancelled-confirmation and abort
 * errors are ignored; every other error is logged and shows the message of
 * the mode with a "View diagnostics" action, except in Cloud mode.
 * Analytics ride along as the toast's errorAnalytics option and the
 * diagnostics host is only called when the action is clicked.
 */
const createSubmitFailureHandler =
  ({
    composerMode,
    conversationId,
    cwd,
    diagnostics,
    followUpType,
    log,
    now = Date.now,
    toast,
  }: SubmitFailureOptions) =>
  (error: unknown, toastId: string, operation?: string) => {
    const analytics = COMPOSER_SUBMIT_ERROR_ANALYTICS;

    if (isRejectedNameError(error)) {
      toast.danger(NAME_REJECTED_MESSAGE, {
        errorAnalytics: {
          ...analytics,
          code: "name_rejected",
          message: NAME_REJECTED_MESSAGE,
        },
      });

      return;
    }

    if (error instanceof PresentationSuggestionCloudUnsupportedError) {
      toast.danger(PRESENTATION_SUGGESTION_CLOUD_MESSAGE, {
        errorAnalytics: {
          ...analytics,
          code: "unsupported_attachment",
          message: PRESENTATION_SUGGESTION_CLOUD_MESSAGE,
        },
      });

      return;
    }

    if (error instanceof ReplyTextOnlyError) {
      toast.danger(REPLY_TEXT_ONLY_MESSAGE, {
        errorAnalytics: {
          ...analytics,
          code: "unsupported_reply",
          message: REPLY_TEXT_ONLY_MESSAGE,
        },
      });

      return;
    }

    if (
      error instanceof ComposerSubmitError ||
      isModelUnavailable(error) ||
      error instanceof AppRequestError
    ) {
      toast.danger(error.message, {
        errorAnalytics: {
          ...analytics,
          message: error.message,
        },
      });

      return;
    }

    if (
      error instanceof ProjectContextSyncError ||
      error instanceof FollowUpConfirmationCancelledError ||
      (error instanceof Error && error.name === "AbortError")
    ) {
      return;
    }

    log?.("[Composer] submit failed", {
      safe: { followUp: followUpType, mode: composerMode },
      sensitive: { cwd, error },
    });

    const primaryAction =
      composerMode === "cloud"
        ? undefined
        : viewDiagnosticsAction(diagnostics, {
            conversationId: conversationId ?? null,
            errorMessage: errorMessage(error),
            occurredAtMs: now(),
            operation:
              operation ??
              (conversationId === undefined || conversationId === null
                ? "startup"
                : "request_submission"),
            surface: "code",
          });

    const message =
      composerMode === "worktree"
        ? localSubmitMessage(error)
        : composerSubmitErrorMessage(error, composerMode);

    toast.danger(message, {
      errorAnalytics: { ...analytics, message },
      id: composerMode === "worktree" ? COMPOSER_TASK_ERROR_TOAST_ID : toastId,
      primaryAction,
    });
  };

export {
  AppHttpError,
  AppRequestError,
  browserTabMentionMessage,
  cloudSubmitMessage,
  COMPOSER_SUBMIT_ERROR_ANALYTICS,
  COMPOSER_TASK_ERROR_TOAST_ID,
  ComposerSubmitError,
  composerSubmitErrorMessage,
  createSubmitFailureHandler,
  errorMessage,
  FollowUpConfirmationCancelledError,
  isModelUnavailable,
  isRejectedNameError,
  localSubmitMessage,
  parseErrorDetail,
  PresentationSuggestionCloudUnsupportedError,
  ProjectContextSyncError,
  ReplyTextOnlyError,
  submitFailureMessage,
  threadReferenceMessage,
  worktreeStateMessage,
};

export type {
  ComposerSubmitMode,
  SubmitDiagnosticsHost,
  SubmitDiagnosticsReport,
  SubmitErrorEnvelope,
  SubmitFailureOptions,
};

